(() => {
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const extra=document.createElement('fieldset');extra.className='product-extra';extra.innerHTML=`<legend>Detalhes do produto</legend><div class="form-grid"><label>Capacidade<input id="detail-capacity" maxlength="80" placeholder="Ex.: 128 GB"></label><label>Cor<input id="detail-color" maxlength="80" placeholder="Ex.: Preto"></label><label>Saúde da bateria (%)<input id="detail-battery" type="number" min="0" max="100" step="1" placeholder="Opcional, para seminovos"></label><label class="full">Garantia deste produto<textarea id="detail-warranty" maxlength="1000" rows="2" placeholder="Informe prazo e condições reais"></textarea></label><label class="full">Ficha técnica e itens inclusos<textarea id="detail-specs" maxlength="3000" rows="4"></textarea></label><label class="full">Fotos adicionais (até 5)<textarea id="detail-gallery" rows="3" placeholder="Um link HTTPS por linha"></textarea></label></div><h3>Opções de cor e capacidade</h3><p class="helper">Se houver opções, o preço e o estoque da vitrine serão calculados a partir delas. Para seminovos com baterias ou condições diferentes, cadastre produtos separados.</p><div id="variant-rows"></div><button type="button" class="secondary" id="add-variant">+ Adicionar opção</button>`;
 $('#product-form .switches').before(extra);
 const addVariant=(v={})=>{if($('#variant-rows').children.length>=20)return;const row=document.createElement('div');row.className='variant-row';row.innerHTML=`<label>Cor<input data-v="color" maxlength="80" value="${esc(v.color)}"></label><label>Capacidade<input data-v="capacity" maxlength="80" value="${esc(v.capacity)}"></label><label>Preço (R$)<input data-v="price" type="number" min="0" max="1000000" step="0.01" placeholder="Sob consulta" value="${v.price==null?'':v.price/100}"></label><label>Estoque<input data-v="stock" type="number" min="0" max="1000000" step="1" value="${v.stock??0}" required></label><button type="button" class="secondary" aria-label="Remover opção">Remover</button>`;row.querySelector('button').onclick=()=>{row.remove();variantState();};$('#variant-rows').append(row);variantState();};
 function variantState(){const has=$('#variant-rows').children.length>0;for(const name of ['price','stock']){$('#product-form').elements[name].readOnly=has;$('#product-form').elements[name].title=has?'Calculado pelas opções abaixo':'';}}
 $('#add-variant').onclick=()=>addVariant();
 window.populateProductDetails=p=>{const d=p?.details||{};for(const k of ['capacity','color','battery','warranty','specs'])$('#detail-'+k).value=d[k]??'';$('#detail-gallery').value=(d.gallery||[]).join('\n');$('#variant-rows').replaceChildren();(d.variants||[]).forEach(addVariant);variantState();};
 window.readProductDetails=()=>({capacity:$('#detail-capacity').value,color:$('#detail-color').value,battery:$('#detail-battery').value===''?null:Number($('#detail-battery').value),warranty:$('#detail-warranty').value,specs:$('#detail-specs').value,gallery:$('#detail-gallery').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),variants:[...$('#variant-rows').children].map(row=>({color:row.querySelector('[data-v=color]').value,capacity:row.querySelector('[data-v=capacity]').value,price:row.querySelector('[data-v=price]').value===''?null:Math.round(Number(row.querySelector('[data-v=price]').value)*100),stock:Number(row.querySelector('[data-v=stock]').value)}))});
 const nav=document.createElement('button');nav.className='nav-item';nav.dataset.view='store';nav.innerHTML='◇ <span>Loja e confiança</span>';$('.sidebar nav').append(nav);
 const section=document.createElement('section');section.id='view-store';section.hidden=true;const fields={warranty:'Garantia e assistência',delivery:'Entrega',pickup:'Retirada na loja',payment:'Formas de pagamento',hours:'Horário de atendimento',teamText:'Apresente a equipe'};
 section.innerHTML=`<div class="page-heading"><div><p class="eyebrow">INFORMAÇÕES CONFIRMADAS</p><h1>Loja e confiança</h1><p>Deixe em branco o que ainda não foi confirmado. Esses campos não aparecem na vitrine.</p></div></div><form id="store-form" class="appearance-card"><fieldset id="store-fields" disabled><div class="form-grid">${Object.entries(fields).map(([k,label])=>`<label class="full">${label}<textarea name="${k}" rows="3" maxlength="2000"></textarea></label>`).join('')}<label class="full">Fotos da equipe (até 4)<textarea name="teamPhotos" rows="3" placeholder="Um link HTTPS por linha. Use fotos autorizadas."></textarea></label></div><h2>Avaliações de clientes</h2><p class="helper">Transcreva avaliações reais, com autorização para exibir o nome e o texto.</p><div id="review-rows"></div><button type="button" id="add-review" class="secondary">+ Adicionar avaliação</button><p id="store-status" role="status"></p><button class="primary" id="save-store">Salvar informações</button></fieldset></form><p id="store-load-error" role="alert"></p><button class="secondary" id="reload-store" type="button">Atualizar informações</button>`;$('.page').append(section);
 let version=0;
 const addReview=(r={})=>{if($('#review-rows').children.length>=10)return;const row=document.createElement('div');row.className='review-editor';row.innerHTML=`<label>Nome do cliente<input data-r="name" value="${esc(r.name)}" maxlength="80" required></label><label>Avaliação<textarea data-r="text" maxlength="1000" rows="3" required>${esc(r.text)}</textarea></label><label class="review-consent"><input type="checkbox" data-r="approved" ${r.approved?'checked':''} required> Confirmo que esta avaliação é real e sua publicação está autorizada.</label><button type="button" class="secondary">Remover avaliação</button>`;row.querySelector('button').onclick=()=>row.remove();$('#review-rows').append(row);};
 $('#add-review').onclick=()=>addReview();
 async function request(options){const r=await fetch('/api/admin/store',options),b=await r.json();if(!r.ok)throw Error(b.error||'Não foi possível carregar.');return b;}
 window.loadStoreContent=async()=>{$('#store-load-error').textContent='';$('#store-fields').disabled=true;try{const data=await request();version=data.version;const f=$('#store-form');for(const k of Object.keys(fields))f.elements[k].value=data.content[k]||'';f.elements.teamPhotos.value=(data.content.teamPhotos||[]).join('\n');$('#review-rows').replaceChildren();(data.content.reviews||[]).forEach(addReview);$('#store-fields').disabled=false;}catch(e){$('#store-load-error').textContent=e.message;}};
 $('#reload-store').onclick=window.loadStoreContent;
 $('#store-form').onsubmit=async e=>{e.preventDefault();const f=e.target,content=Object.fromEntries(new FormData(f));content.teamPhotos=f.elements.teamPhotos.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);content.reviews=[...$('#review-rows').children].map(r=>({name:r.querySelector('[data-r=name]').value,text:r.querySelector('[data-r=text]').value,approved:r.querySelector('[data-r=approved]').checked}));$('#save-store').disabled=true;try{const data=await request({method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({content,version})});version=data.version;$('#store-status').textContent='Informações salvas na vitrine.';}catch(err){$('#store-status').textContent=err.message;}finally{$('#save-store').disabled=false;}};
})();
